import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent inverse of four bounded ports, full archive, schema and all original methods. */
public final class NegativeSelfDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",N=P+"NativeSourceNegativeSelf";
 static void need(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var existing=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){existing.add(e.getName());var next=jar.getJarEntry(e.getName());need(next!=null,"no removed entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(next).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!existing.contains(e.getName()))fresh.add(e.getName());need(changed.equals(Set.of(PC+".class"))&&fresh.equals(Set.of(N+".class")),"exact archive");var old=FreezeSourceTargetDelta.read(base,PC);var now=FreezeSourceTargetDelta.read(jar,PC);need(old.fields.size()==now.fields.size()&&old.methods.size()==now.methods.size(),"same schema");for(int i=0;i<old.fields.size();i++){var f=old.fields.get(i);var g=now.fields.get(i);need(f.access==g.access&&f.name.equals(g.name)&&f.desc.equals(g.desc)&&Objects.equals(f.value,g.value),"original field");}int selects=0,targets=0;
  for(var m:old.methods){var actual=now.methods.stream().filter(x->x.name.equals(m.name)&&x.desc.equals(m.desc)).findFirst().orElseThrow();for(var n:actual.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(N)){
    need(Set.of("nativeMaterialEntangleBody","nativeMaterialEraseBody").contains(m.name),"only two original bodies");String spell=P+"BattleSpellCatalog$"+(m.name.equals("nativeMaterialEntangleBody")?"EntangleSpell":"EraseMagicSpell");
    if(call.name.equals("selected")){var sequence=new ArrayList<AbstractInsnNode>();var cursor=n;for(int i=0;i<5;i++){cursor=FreezeAcceptedMethods.prev(cursor);sequence.add(cursor);}Collections.reverse(sequence);int[]vars={0,4,8,2};for(int i=0;i<4;i++)need(sequence.get(i)instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==vars[i],"same captured original selected arguments");need(sequence.get(4)instanceof MethodInsnNode id&&id.owner.equals(spell)&&id.name.equals("skillId")&&id.desc.equals("()I"),"actual model skill");var store=FreezeSourceTargetDelta.next(n);need(store instanceof VarInsnNode v&&v.getOpcode()==ASTORE&&v.var==8,"same original target local");for(var x:sequence)actual.instructions.remove(x);actual.instructions.remove(store);actual.instructions.remove(n);selects++;}
    else if(call.name.equals("target")){var id=FreezeAcceptedMethods.prev(n);var model=FreezeAcceptedMethods.prev(id);need(model instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==2&&id instanceof MethodInsnNode c&&c.owner.equals(spell)&&c.name.equals("skillId")&&c.desc.equals("()I"),"exact added model argument");actual.instructions.remove(model);actual.instructions.remove(id);call.owner=P+"GameHub";call.name="canAttack";call.desc="(JL"+PC+";L"+PC+";)Z";call.setOpcode(INVOKEVIRTUAL);call.itf=false;targets++;}else throw new AssertionError("unexpected new call");
   }need(Arrays.equals(FreezeSourceTargetDelta.body(old,m,m.name,m.access),FreezeSourceTargetDelta.body(now,actual,m.name,m.access)),"every original numeric/cost/effect method inverse "+m.name);
  }need(selects==2&&targets==2,"four exact ports");var helper=FreezeSourceTargetDelta.read(jar,N);need(helper.fields.isEmpty(),"stateless helper");for(var m:helper.methods)for(var n:m.instructions){need(!(n instanceof TypeInsnNode t&&t.getOpcode()==NEW),"no new workers/TLS/registries");if(n instanceof MethodInsnNode c)need(!c.owner.startsWith("java/sql/")&&!c.owner.startsWith("java/nio/file/")&&!c.owner.contains("GameStateStore")&&!Set.of("set","activate","debitMp","admit","commit").contains(c.name),"read-only selection/faction helper");}
 }System.out.println("PASS independent self archive/schema/all-original-method inverse; original cost/probability/locks retained");}
}
